begin;
set local search_path='';
set local statement_timeout='30s';
set local lock_timeout='5s';
create temporary table alq_f1a_qualification_context(
  run_id uuid primary key) on commit drop;
insert into pg_temp.alq_f1a_qualification_context(run_id)
values ('f1a20260-8210-0000-0000-000000000001'::uuid);
select pg_catalog.set_config('application_name',
  'alq_f1a_barrier:f1a20260821000000000000000000001:QA_IDEMPOTENCIA_MISMA_CLAVE_HASH:A',false);
select pg_catalog.set_config('request.jwt.claim.sub',(
  select pu.auth_user_id::text
  from alq.alq_capacidad_admin ca
  join alq.alq_parte_usuario pu on pu.id=ca.parte_usuario_id
  where statement_timestamp()<@ca.vigencia
    and statement_timestamp()<@pu.vigencia
  order by ca.id limit 1),true);
select pg_catalog.set_config('request.jwt.claim.role','authenticated',true);
select pg_catalog.set_config('request.jwt.claims',(
  select jsonb_build_object('sub',pu.auth_user_id,'role','authenticated',
    'app_metadata',jsonb_build_object('rol','admin'))::text
  from alq.alq_capacidad_admin ca
  join alq.alq_parte_usuario pu on pu.id=ca.parte_usuario_id
  where statement_timestamp()<@ca.vigencia
    and statement_timestamp()<@pu.vigencia
  order by ca.id limit 1),true);
create temporary table alq_f1a_barrier_peer(pid integer primary key) on commit drop;
create temporary table alq_f1a_side_result(envelope jsonb not null) on commit drop;
do $alq_f1a_barrier$
declare
  v_peer integer;
  v_deadline timestamptz:=clock_timestamp()+interval '10 seconds';
  v_envelope jsonb;
begin
  perform pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended(
    'alq_f1a_barrier:signal:f1a20260821000000000000000000001:QA:A',0));
  loop
    select a.pid into v_peer
    from pg_catalog.pg_stat_activity a
    where a.datname=current_database()
      and a.pid<>pg_catalog.pg_backend_pid()
      and a.application_name='alq_f1a_barrier:f1a20260821000000000000000000001:QA_IDEMPOTENCIA_MISMA_CLAVE_HASH:B'
    order by a.pid limit 1;
    exit when found;
    if clock_timestamp()>=v_deadline then
      raise exception 'ALQ_F1A_QA_BARRIER_PEER_TIMEOUT';
    end if;
    perform pg_catalog.pg_sleep(0.02);
  end loop;
  insert into pg_temp.alq_f1a_barrier_peer values(v_peer);
  v_envelope:=public.alq_admin_preparar_v2(
    'f1a20260-8210-4000-8000-00000000000a'::uuid,
    'nota_emitir',
    jsonb_build_object(
      'nota_ref','f1a20260-8210-4000-8000-0000000000aa',
      'tipo','credito',
      'cargo_id','f1a20260-8210-4000-8000-0000000000cc',
      'monto',1,'moneda','ARS',
      'motivo','calificacion sintetica F1-A',
      'fecha','2026-08-21T12:00:00Z'));
  if v_envelope->>'estado'<>'rechazada_sin_fila'
     or v_envelope->>'codigo'<>'ALQ_F1A_REFERENCIA_NO_EXISTE'
     or coalesce((v_envelope->>'ok')::boolean,true) then
    raise exception 'ALQ_F1A_QA_RECHAZO_SIN_FILA_INVALIDO';
  end if;
  insert into pg_temp.alq_f1a_side_result values(v_envelope);
end
$alq_f1a_barrier$;
select 'ALQ_F1A_CONCURRENCY_SIDE|'||jsonb_build_object(
  'schema_version',1,
  'run_id','f1a20260821000000000000000000001',
  'source_sha256','d05e853bf1447e9df3493eea1fd8c2893f8b535b940ff091646ec35c0293f701',
  'captured_utc',to_char(clock_timestamp() at time zone 'UTC',
    'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
  'case','QA_IDEMPOTENCIA_MISMA_CLAVE_HASH',
  'side','A',
  'status','RECHAZADA_SIN_FILA',
  'pid',pg_catalog.pg_backend_pid(),
  'peer_pid',(select pid from pg_temp.alq_f1a_barrier_peer),
  'barrier_observed',true,
  'financial_success',false,
  'residual_rows',0);
commit;

